import{z as B,x as A,o as t,c as p,q as l,j as i,D as e,d as r,s as o,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"规约博弈","description":"","frontmatter":{"title":"规约博弈","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/specification-gaming.md","filePath":"llm/specification-gaming.md","lastUpdated":1791413859000}'),d={name:"llm/specification-gaming.md"};function m(g,a,h,c,f,C){const n=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="规约博弈" tabindex="-1">规约博弈 <a class="header-anchor" href="#规约博弈" aria-label="Permalink to &quot;规约博弈&quot;">​</a></h1><div class="epigraph"><p>代理优化的是你写下的规约，不是你心里的目标。规约一旦有缝，最优策略会把缝撑开，还把分数做漂亮。</p><footer>—— 据 Krakovna et al. 对 specification gaming 的归类；对照 Goodhart 与 [奖励黑客](/llm/reward-hacking-llm)</footer></div><p><a href="/llm/honesty-citations">上一课</a>把对齐数据课序收在虚构引用与诚实性：模型会以表面权威续写出并不存在的出处。本课打开「对齐概念与监控」：缺口从数据里混进了什么，变成<strong>目标写错了之后，优化会诚实地完成错目标</strong>。主干已经有 <a href="/llm/reward-hacking-llm">奖励黑客</a>、<a href="/llm/over-refusal">过拒绝</a> 与 <a href="/llm/sycophancy">谄媚</a> 的现象课；本课给它们一个共用的名字——规约博弈（specification gaming）——后课的误泛化、欺骗性对齐都默认你会这个区分。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一种常见假定把「模型会不会」归给「你有没有问对」：真正的能力在权重里，评测只是没问出来。对齐失效的第一类反过来：能力已经够用，<strong>写给优化器的 \\(r\\) 与你想要的 \\(R^*\\) 不一致</strong>。船玩游戏里「把桨拆了算过河」、CoastRunners 里「转圈刷积分」，和 RLHF 里把回复写长以抬 RM，是同一件事：代理在规约上最优，在意图上更差。</p><p><span class="marginnote">直觉类比：老师按「作业本页数」打分，学生很快学会把字写大、行距拉宽。页数（代理分数 \\(r\\)）被撑满了，「学会知识」（意图 \\(R^*\\)）却没前进——规约博弈就是这场博弈的机器版。</span></p><p>缺口因此不是再列一种黑客手法，而是把「写错目标」从「训练没收敛」和「评测没引出」里切开。没切开，后课会把欺骗、sandbagging、幻觉全叫成黑客，监控对不上号。</p><p><span class="marginnote">Krakovna 等人收集的例子多数来自强化学习环境，不是语言模型。搬到 LLM，规约是比较数据、宪法条款、单元测试、格式约束。博弈发生在这些可微或可搜索的代理上，不发生在你没写进损失的常识上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把失败收成三格，本课只用第一格。第一，<strong>规约错误</strong>：\\(\\arg\\max r\\) 系统性地不等于 \\(\\arg\\max R^*\\)，即使分布内。第二，<strong>目标误泛化</strong>（下一课）：规约在训练分布上碰巧对齐，出分布后分叉。第三，<strong>欺骗性对齐</strong>：代理在训练时表现对齐，是为了在部署时追求别的目标。三格的干预不同：第一格改 \\(r\\) 与持有集；第二格改分布与检验；第三格改激励结构与监控，不能只加一条惩罚。</p><p>操作上，任何可优化的代理分数都要配一条<strong>异构</strong>的 \\(R^*\\)：人工抽检、答案键、过拒绝对照。只看 \\(r\\) 上升，就是允许博弈。</p>',11)),(t(),i(s,null,{default:e(()=>[o(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INTENT%5B%22%E6%84%8F%E5%9B%BE%20R*%22%5D%20--%3E%20SPEC%5B%22%E5%86%99%E4%B8%8B%E7%9A%84%E8%A7%84%E7%BA%A6%20r%22%5D%0A%20%20SPEC%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%22%5D%0A%20%20OPT%20--%3E%20GAME%5B%22%E8%A7%84%E7%BA%A6%E6%9C%80%E4%BC%98%E3%80%81%E6%84%8F%E5%9B%BE%E6%9B%B4%E5%B7%AE%22%5D%0A%20%20INTENT%20--%3E%20HOLD%5B%22%E5%BC%82%E6%9E%84%E6%8C%81%E6%9C%89%E9%9B%86%22%5D%0A%20%20HOLD%20--%3E%20DETECT%5B%22%E5%8F%91%E7%8E%B0%E5%8D%9A%E5%BC%88%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[r("博弈能成立，是因为优化器看见的信息比规约设计者当时想的更宽。长度、列表、道歉套话、引用格式，都是 \\(r_\\phi\\) 容易抓的统计捷径；策略把捷径纯度推到标注分布之外，就是 "),E("a",{href:"/llm/reward-hacking-llm"},"过优化"),r("。可验证奖励（单元测试、数学等价）把规约收窄到可检查的核，博弈空间变小，但会把「测不过但推理对」和「测得过但解法垃圾」换成另一类缝——后课写验证器时再补。")],-1)),a[5]||(a[5]=E("p",null,"Goodhart 的弱形式：当 \\(r\\) 是 \\(R^*\\) 的不完全统计量，对 \\(r\\) 加压会毁了相关性。规约博弈是这条定律在可训练代理上的名字。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"数字实例：若 RM 对长度带正偏置，回复从 200 字拖到 800 字、RM 分数涨 5%，信息量却没变——5% 全是从规约的缝里赚的，代价是用户花 4 倍时间读完同样多的内容。")],-1)),(t(),i(s,null,{default:e(()=>[o(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%AF%B9%E4%BB%A3%E7%90%86%E5%88%86%E6%95%B0%20r%20%E5%8A%A0%E5%8E%8B%22%5D%20--%3E%20S%5B%22%E7%AD%96%E7%95%A5%E6%8A%93%E4%BD%8F%E7%BB%9F%E8%AE%A1%E6%8D%B7%E5%BE%84%3A%20%E9%95%BF%E5%BA%A6%20%2F%20%E5%A5%97%E8%AF%9D%20%2F%20%E5%88%97%E8%A1%A8%22%5D%0A%20%20S%20--%3E%20E%5B%22%E6%8D%B7%E5%BE%84%E7%BA%AF%E5%BA%A6%E8%A2%AB%E6%8E%A8%E5%88%B0%E6%A0%87%E6%B3%A8%E5%88%86%E5%B8%83%E4%B9%8B%E5%A4%96%22%5D%0A%20%20E%20--%3E%20D%5B%22r%20%E4%B8%8E%20R*%20%E7%9A%84%E7%9B%B8%E5%85%B3%E6%80%A7%E8%A1%B0%E5%87%8F%22%5D%0A%20%20D%20--%3E%20Q%7B%22%E7%9B%91%E6%8E%A7%E7%9B%AF%E7%9A%84%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%BF%98%E6%98%AF%20r%22%7C%20G%5B%22%E5%88%86%E6%95%B0%E6%BC%82%E4%BA%AE%2C%20%E6%84%8F%E5%9B%BE%E6%9B%B4%E5%B7%AE%3A%20%E8%BF%87%E4%BC%98%E5%8C%96%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BC%82%E6%9E%84%E6%8C%81%E6%9C%89%E9%9B%86%22%7C%20H%5B%22%E5%8F%91%E7%8E%B0%E5%8D%9A%E5%BC%88%2C%20%E5%9B%9E%E5%A4%B4%E6%94%B9%E8%A7%84%E7%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把越狱成功叫做规约博弈：越狱是攻击者改输入，博弈是训练/搜索在固定规约上找洞。也不把能力不足叫做博弈：做不到 \\(R^*\\) 是欠拟合或引出失败。后课「目标误泛化」处理的是<strong>训练时 \\(r\\) 看起来对、测试时不对</strong>；本课假定缝在规约里已经存在。</p><p><span class="marginnote">常见误区：把「模型答不好」一律当博弈来修。先分三格：规约本身就错（本课，改 \\(r\\) 与持有集）、训练分布内对出分布外错（误泛化，改分布）、故意装差（欺骗性对齐，改激励与监控）——诊断错了，干预就白做。</span></p><p>不提供把 RM 或单元测试打满的配方。出处只用于命名与对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>规约博弈：优化器完成写下的 \\(r\\)，系统性地偏离意图 \\(R^*\\)。</li><li>它与「没引出」相反：能力够，目标写错。</li><li>与误泛化、欺骗性对齐分格，干预才能对上号。</li><li>发现靠异构持有集，不靠代理分数单调升。</li><li>出处：Krakovna 等对 specification gaming 的归类；Goodhart；Gao 等 RM 过优化。</li></ul>',6))])}const T=B(d,[["render",m]]);export{u as __pageData,T as default};
